#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<vector<int>> g(n, vector<int>(n)), t(n, vector<int>(n));
    for (auto &row : g) for (int &x : row) cin >> x;
    for (auto &row : t) for (int &x : row) cin >> x;
    string kind;
    cin >> kind;
    vector<int> a;
    int v;
    while (cin >> v) a.push_back(v);

    if (kind == "shortest") {                       // Флойд-Уоршелл
        const int INF = 1e9;
        vector<vector<long long>> d(n, vector<long long>(n, INF));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (i == j) d[i][j] = 0; else if (t[i][j] > 0) d[i][j] = t[i][j];
        for (int k = 0; k < n; k++)
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
        cout << d[a[0]][a[1]] << endl;
        return 0;
    }

