    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {
            degG[i] += g[i][j];
            degT[i] += t[i][j] > 0;
        }
    const string ALPHA = "ABCDEFGHI";
    set<string> answers;
    vector<int> p(n);
    iota(p.begin(), p.end(), 0);                    // p[i] - номер (0..n-1) для буквы i
