        for (int i = 0; i < n && ok; i++)
            for (int j = 0; j < n && ok; j++)
                if ((g[i][j] == 1) != (t[p[i]][p[j]] > 0)) ok = false;
        if (!ok) continue;
        string ans;
        if (kind == "road") {
            ans = to_string(t[p[a[0]]][p[a[1]]]);
        } else if (kind == "sum2") {
            ans = to_string(t[p[a[0]]][p[a[1]]] + t[p[a[2]]][p[a[3]]]);
        } else if (kind == "pair") {
            int x = p[a[0]] + 1, y = p[a[1]] + 1;
            if (x > y) swap(x, y);
            ans = to_string(x) + to_string(y);
        } else if (kind == "letters") {
            vector<int> inv(n);
            for (int i = 0; i < n; i++) inv[p[i]] = i;
            for (int j = 0; j < n; j++) ans += ALPHA[inv[j]];
        } else if (kind == "cond") {
            if (!(t[p[a[2]]][p[a[3]]] > t[p[a[4]]][p[a[5]]])) continue;
            ans = to_string(t[p[a[0]]][p[a[1]]]);
        } else {
            return 1;
        }
        answers.insert(ans);
    } while (next_permutation(p.begin(), p.end()));
    if (answers.size() == 1) cout << *answers.begin() << endl;
    else cout << "AMBIGUOUS" << endl;
    return 0;
}

